module Top;
    typedef enum logic [1:0] { RED, GREEN, BLUE } color_t;
    color_t colors[4] = '{RED, BLUE, GREEN, BLUE};
    color_t c[$];
    int q[$] = '{5, 1, 4, 1, 9, 2, 6};
    int r[$], lowest[$];
    string names[$] = '{"bob", "alice", "carol", "alice"};
    string s[$];
    initial begin
        lowest = '{4};
        r = q.find with (item > 3);
        $display("operand equality %0d", r.min() == lowest);
        $display("chained size %0d", q.find with (item == 1).size());
        r = q.find with (q.find(y) with (y == item).size() > 1);
        $display("nested size %0d", r.size());
        s = names.min();
        $display("string min %s", s[0]);
        c = colors.find_first with (item.next() == BLUE);
        $display("enum next size %0d", c.size());
    end
endmodule
